/bin/zsh -lc "apply_patch <<'PATCH'
*** Begin Patch
*** Update File: TopModule.sv
@@
     always@(posedge clk or negedge rst_n)begin
         if("'!rst_n) Q <= '"'d0;
-        else Q <= {~Q[1], Q[3 : 1]};
+        else Q <= {~Q[0], Q[3 : 1]};
     end
 endmodule
*** End Patch
PATCH

cat > /tmp/tb_topmodule.sv <<'EOF'
module tb;
  reg clk = 0;
  reg rst_n = 0;
  wire [3:0] Q;

  TopModule dut(.clk(clk), .rst_n(rst_n), .Q(Q));

  always #5 clk = ~clk;

  reg [3:0] expected [0:8];
  integer i;
  initial begin
    expected[0]=4'b0000;
    expected[1]=4'b1000;
    expected[2]=4'b1100;
    expected[3]=4'b1110;
    expected[4]=4'b1111;
    expected[5]=4'b0111;
    expected[6]=4'b0011;
    expected[7]=4'b0001;
    expected[8]=4'b0000;

    #1;
    if (Q "'!== 4'"'b0000) begin
      "'$display("FAIL reset state Q=%b", Q);
      $finish(1);
    end

    #2 rst_n = 1;
    for (i = 1; i <= 8; i = i + 1) begin
      @(posedge clk);
      #1;
      if (Q !== expected[i]) begin
        $display("FAIL step %0d got=%b exp=%b", i, Q, expected[i]);
        $finish(1);
      end
    end
    $display("PASS");
    $finish;
  end
endmodule
EOF

iverilog -g2012 -o /tmp/simv TopModule.sv /tmp/tb_topmodule.sv && vvp /tmp/simv'

